def _result(ok, detail):
    return {"score": 1 if ok else 0, "detail": detail}


def _db(workspace):
    return Path(workspace).parent / "system" / "servicenow_fuel_risk_governance" / "state.db"


def _doc_text(path):
    from docx import Document
    doc = Document(str(path))
    parts = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        parts.extend(" | ".join(cell.text for cell in row.cells) for row in table.rows)
    return "\n".join(parts)


def check_governance_final_state(workspace):
    try:
        con = sqlite3.connect(_db(workspace)); con.row_factory = sqlite3.Row
        proposal = con.execute("SELECT * FROM risk_proposals WHERE proposal_id='FRP-2025-DP-Q4-V2'").fetchone()
        actions = con.execute("SELECT * FROM approval_actions WHERE proposal_id='FRP-2025-DP-Q4-V2' ORDER BY sequence_number").fetchall()
        if not proposal or proposal["proposal_status"] != "APPROVED" or len(actions) != 5:
            return _result(False, "Current V2 is not APPROVED with exactly five ordered actions.")
        prior = [(r["approval_action_id"], r["decision"], r["sequence_number"], r["idempotency_key"]) for r in actions[:4]]
        expected = [("APR-2025-0912-063", "CONDITIONAL_APPROVE", 1, "idem-frp-dp-v2-park-01"), ("APR-2025-0912-071", "CONCUR", 2, "idem-frp-dp-v2-chen-02"), ("APR-2025-0912-079", "APPROVE", 3, "idem-frp-dp-v2-soto-03"), ("APR-2025-0912-082", "CONCUR", 4, "idem-frp-dp-v2-record-04")]
        if prior != expected:
            return _result(False, "Pre-existing V2 approval history changed.")
        action = actions[4]
        reviewer = con.execute("SELECT active_flag FROM governance_parties WHERE party_id=?", (action["reviewer_party_id"],)).fetchone()
        text = (action["condition_text"] or "").lower()
        required = ["daily", "reforecast", "pipeline", "capacity", "nomination", "control"]
        residual_ok = "residual" in text or ("separat" in text and all(x in text for x in ["basis", "transport", "imbalance", "dispatch", "volume"]))
        if not (action["decision"] == "APPROVE" and action["sequence_number"] == 5 and action["is_authorized_reviewer"] == 1 and reviewer and reviewer[0] == 1 and action["authorization_scope"] and action["idempotency_key"] and all(x in text for x in required) and residual_ok):
            return _result(False, "Final action lacks authorized APPROVE, fresh idempotency, or required conditions.")
        event = con.execute("SELECT * FROM governance_events WHERE source_system='SERVICENOW' AND source_record_id=? AND event_type='APPROVAL_RECORDED'", (action["approval_action_id"],)).fetchone()
        if not event or event["event_status"] != "APPROVED" or event["evidence_contracts"] != 203 or event["evidence_quantity_mmbtu"] != 1437286:
            return _result(False, "Matching approval event or evidence is incorrect.")
        return _result(True, "V2 is APPROVED with a new authorized sequence-5 action and matching event; prior actions are retained.")
    except Exception as exc:
        return _result(False, f"Governance check error: {exc}")
    finally:
        try: con.close()
        except Exception: pass


def check_approval_receipt(workspace):
    path = Path(workspace) / RECEIPT
    if not path.is_file():
        return _result(False, "Approval receipt DOCX is missing.")
    try:
        text = _doc_text(path).lower()
        compact = re.sub(r"[^a-z0-9.]", "", text)
        required = ["frp-2025-dp-q4-v2", "203", "2030000", "1437286", "809051.086"]
        concepts = ["daily", "reforecast", "pipeline", "capacity", "nomination", "basis", "transport", "imbalance", "dispatch", "volume"]
        date_ok = "september 19, 2025" in text or "2025-09-19" in text or "09/19/2025" in text
        ok = date_ok and all(x in compact for x in ["frp2025dpq4v2", "203", "2030000", "1437286", "809051.086"]) and all(x in text for x in concepts)
        return _result(ok, "Receipt contains the current proposal, valuation date, contract/volume anchors, and condition/risk concepts." if ok else "Receipt is missing one or more exact anchors or concepts.")
    except Exception as exc:
        return _result(False, f"Receipt check error: {exc}")


def check_workspace_integrity(workspace):
    root = Path(workspace)
    for rel, digest in BASELINE.items():
        p = root / rel
        if not p.is_file() or hashlib.sha256(p.read_bytes()).hexdigest() != digest:
            return _result(False, f"Supplied workspace file changed: {rel}")
    allowed = set(BASELINE) | {str(RECEIPT), "answer" + ".md"}
    extras = [str(p.relative_to(root)) for p in root.rglob("*") if p.is_file() and str(p.relative_to(root)) not in allowed and not (p.suffix == ".pyc" and "__pycache__" in p.parts)]
    return _result(not extras, "All source workspace files are unchanged." if not extras else f"Unexpected workspace files: {extras}")


def check_history_integrity(workspace):
    try:
        con = sqlite3.connect(_db(workspace)); con.row_factory = sqlite3.Row
        v1 = con.execute("SELECT proposal_status, current_version_flag, benchmark_contracts, authorized_basis_mmbtu FROM risk_proposals WHERE proposal_id='FRP-2025-DP-Q4-V1'").fetchone()
        if tuple(v1) != ("SUPERSEDED", 0, 198, 1398600):
            return _result(False, "Superseded V1 proposal was changed.")
        count = con.execute("SELECT count(*) FROM control_requirements WHERE proposal_id='FRP-2025-DP-Q4-V2'").fetchone()[0]
        if count != 8:
            return _result(False, "V2 control requirements were deleted.")
        return _result(True, "Superseded proposal and pre-existing control history remain intact.")
    except Exception as exc:
        return _result(False, f"History check error: {exc}")
    finally:
        try: con.close()
        except Exception: pass
